//
//  PandoraCryptoTests.swift
//  PandoraCoreTests
//
//  Blowfish known-answer vectors. Every expected ciphertext below was
//  generated by running the vendored reference implementation —
//  `pithos/pandora/blowfish.py` (Versile/Schneier, GPL) driven by
//  `pithos.pandora.pandora_encrypt`'s exact pad/encrypt/hex pipeline —
//  in this repository's toolchain, not transcribed from documentation.
//
//  Keys: `PandoraAPI.encryptKey` = 6#26FRL$ZWD,
//        `PandoraAPI.decryptKey`  = R=U!LH$O2B#
//  (pithos/pandora/data.py, client_keys['android-generic']).
//

import XCTest
@testable import PandoraCore

final class PandoraCryptoTests: XCTestCase {

    private let encryptKey = PandoraAPI.encryptKey   // 6#26FRL$ZWD
    private let decryptKey = PandoraAPI.decryptKey   // R=U!LH$O2B#

    // MARK: - Known-answer vectors

    func testKnownAnswerSingleAlignedBlock() throws {
        let plaintext = Data("01234567".utf8)                       // 8 bytes, aligned
        let hex = try PandoraCrypto.encryptToHex(plaintext, key: encryptKey)
        XCTAssertEqual(hex, "55ef75076b9dc2c6")
    }

    func testKnownAnswerUnalignedZeroPadding() throws {
        let plaintext = Data("hello pandora".utf8)                  // 13 bytes → pad 3
        let hex = try PandoraCrypto.encryptToHex(plaintext, key: encryptKey)
        XCTAssertEqual(hex, "914aeef8c87310ac6fc02f37100cfad4")
    }

    func testKnownAnswerJSONRequestBody() throws {
        let plaintext = Data(#"{"username":"android","password":"AC7IBG09A3DTSYM4R41UJWL07VLN8JI7"}"#.utf8)
        let hex = try PandoraCrypto.encryptToHex(plaintext, key: encryptKey)
        XCTAssertEqual(hex, "0d44893efd67244852082c9157fdc86eac0755dbeb6245297e47279937cf2685ad5cb304a90eb6d92dfe517582d5d15b9a0b561e80200fc620becac700f586e7afe88c80c0e47595")
    }

    func testKnownAnswerSchneierZeroVector() throws {
        // Classic Blowfish KAT (Schneier): zero key, zero block.
        let hex = try PandoraCrypto.encryptToHex(Data(repeating: 0, count: 8), key: String(repeating: "\0", count: 8))
        XCTAssertEqual(hex, "4ef997456198dd78")
    }

    // MARK: - syncTime decode path (decryptKey)

    func testSyncTimeFieldDecryptSlice() throws {
        // Fixture: server-side encrypt of a pithos-shaped syncTime plaintext
        // under decryptKey. Client must recover bytes[4:14] as the timestamp.
        let ciphertextHex = "7cc6426208f75478c3bf1447786fe256a5707adaf92eb564"
        let decrypted = try PandoraCrypto.decryptFromHex(ciphertextHex, key: decryptKey)
        XCTAssertEqual(decrypted.prefix(4), Data("PNDS".utf8))
        let stamp = decrypted[4..<14]
        XCTAssertEqual(Data(stamp), Data("1337000000".utf8))
    }

    // MARK: - Round trip

    func testEncryptDecryptRoundTripAlignedInput() throws {
        // 48 bytes — already block-aligned, so zero-padding adds nothing and
        // the round trip is exact.
        let plaintext = Data(#"{"method":"auth.userLogin","password":"hunter2"}"#.utf8)
        let hex = try PandoraCrypto.encryptToHex(plaintext, key: encryptKey)
        let recovered = try PandoraCrypto.decryptFromHex(hex, key: encryptKey)
        XCTAssertEqual(recovered, plaintext)
    }

    func testEncryptDecryptRoundTripUnalignedInput() throws {
        // "hello pandora" is 13 bytes → padded to 16 with 3 zero bytes, which
        // decryption does NOT strip: the original is a prefix of the result.
        let plaintext = Data("hello pandora".utf8)
        let hex = try PandoraCrypto.encryptToHex(plaintext, key: encryptKey)
        let recovered = try PandoraCrypto.decryptFromHex(hex, key: encryptKey)
        XCTAssertEqual(recovered.count, 16)
        XCTAssertEqual(recovered.prefix(plaintext.count), plaintext)
        XCTAssertEqual(recovered.suffix(3), Data([0, 0, 0]))
    }

    func testEmptyInputIsPassThrough() throws {
        XCTAssertEqual(try PandoraCrypto.encrypt(Data(), key: encryptKey), Data())
        XCTAssertEqual(try PandoraCrypto.decrypt(Data(), key: encryptKey), Data())
    }

    // MARK: - Error paths

    func testOddLengthHexThrows() {
        XCTAssertThrowsError(try PandoraCrypto.data(fromHex: "abc")) { error in
            XCTAssertEqual(error as? PandoraCryptoError, .invalidHex)
        }
    }

    func testNonHexCharactersThrow() {
        XCTAssertThrowsError(try PandoraCrypto.data(fromHex: "zz11")) { error in
            XCTAssertEqual(error as? PandoraCryptoError, .invalidHex)
        }
    }

    func testMisalignedCiphertextThrows() {
        XCTAssertThrowsError(try PandoraCrypto.decrypt(Data(repeating: 1, count: 7), key: encryptKey)) { error in
            XCTAssertEqual(error as? PandoraCryptoError, .notBlockAligned(actual: 7))
        }
    }

    // MARK: - Wire conveniences use the pinned constants

    func testEncryptRequestBodyUsesEncryptKey() throws {
        let body = Data("{}".utf8)
        let viaConvenience = try PandoraCrypto.encryptRequestBody(body)
        let viaExplicit = try PandoraCrypto.encryptToHex(body, key: "6#26FRL$ZWD")
        XCTAssertEqual(viaConvenience, viaExplicit)
    }

    func testDecryptHexFieldUsesDecryptKey() throws {
        let fixture = try PandoraCrypto.encryptToHex(Data("sync".utf8), key: "R=U!LH$O2B#")
        let recovered = try PandoraCrypto.decryptHexField(fixture)
        // 4-byte plaintext round-trips with zero padding to 8.
        XCTAssertEqual(recovered.prefix(4), Data("sync".utf8))
    }
}
